previewAimAssist.source:
function previewAimAssist(ctx) {
  // a crosshair sweeps past a rival; the assist bends its path onto the target (strength = the slider)
  const el = h('div', { class: 'iw-pv iw-pv--aim', html: frameSVG(`
    <g transform="translate(160 104)"><ellipse cx="0" cy="34" rx="30" ry="7" fill="#000" opacity=".16"/>
      <g transform="translate(-22 -26) scale(.7)" style="color:var(--b)">${SQUID.replace('class="iw-ico iw-squid"', 'x="0" y="0" width="64" height="64"')}</g></g>
    <path class="iw-pv-aim__trail" d="M20 90 L300 90" fill="none"/>
    <g class="iw-pv-aim__x"><circle r="13" fill="none" stroke="#fff" stroke-width="4"/><circle r="13" fill="none" stroke="${K}" stroke-width="1.6"/><circle r="3" fill="#fff" stroke="${K}" stroke-width="1.4"/>
      <path d="M0 -21 V-15 M0 21 V15 M-21 0 H-15 M21 0 H15" stroke="#fff" stroke-width="3.2" stroke-linecap="round"/></g>`) + '<div class="iw-pv-cap"></div>' });
  const xEl = el.querySelector('.iw-pv-aim__x'), trail = el.querySelector('.iw-pv-aim__trail'), cap = el.querySelector('.iw-pv-cap');
  let v = clamp(+ctx.value || 0), t = 0;
  const set = (nv) => { v = clamp(+nv || 0); cap.innerHTML = v <= 0.001 ? tr('Aim assist <b>OFF</b>') : tr('Pull strength <b>{n}%</b>', { n: Math.round(v * 100) }); };
  set(v);
  return {
    el, set,
    tick: (dt) => {
      t = (t + dt / 2.6) % 1;
      // raw sweep left → right; assisted path eases toward the target centre (160, 100) as it passes
      const x0 = 30 + t * 260, near = Math.exp(-Math.pow((x0 - 160) / 60, 2));
      const x = x0 + (160 - x0) * near * v * 0.55, y = 64 + (100 - 64) * near * v;
      xEl.setAttribute('transform', `translate(${x.toFixed(1)} ${y.toFixed(1)})`);
      if (t < 0.02) trail.setAttribute('d', `M${x.toFixed(1)} ${y.toFixed(1)}`);
      else trail.setAttribute('d', `${trail.getAttribute('d')} L${x.toFixed(1)} ${y.toFixed(1)}`);
    },
  };
}

_placeCall.source:
_placeCall(dt) {
    const S = this.S, u = this._u(), W = innerWidth, H = innerHeight;
    const w = this._anchor('shellTop', 1.9, this._tmp);
    const sp = w && this._screen(w, this._callScratch || (this._callScratch = {}));
    if (!sp) return;
    let x = sp.x, y = sp.y, edge = false, ang = 0;
    let dx = x - W / 2, dy = y - H / 2;
    if (sp.behind) { dx = -dx; dy = -dy; if (Math.abs(dx) < 1 && Math.abs(dy) < 1) dy = 1; }
    const mx = u * 7, myT = u * 16, myB = u * 7;
    if (!sp.behind && x >= mx && x <= W - mx && y < myT) y = myT;   // on screen but tall: sit just under the boss bar
    if (sp.behind || x < mx || x > W - mx || y > H - myB) {
      edge = true;
      ang = Math.atan2(dy, dx);
      const ex = W / 2 - mx, ey = (H - myT - myB) / 2, cyE = myT + ey;
      const k = Math.min(ex / Math.max(1e-3, Math.abs(Math.cos(ang))), ey / Math.max(1e-3, Math.abs(Math.sin(ang))));
      x = W / 2 + Math.cos(ang) * k; y = cyE + Math.sin(ang) * k;
    } else {
      // never over the crosshair: push out of an ellipse around the centre (upward when dead centre)
      const rx = u * 15, ry = u * 10.5;
      const ddx = x - W / 2, ddy = y - H / 2, r = (ddx / rx) ** 2 + (ddy / ry) ** 2;
      if (r < 1) {
        if (r < 1e-4) { x = W / 2; y = H / 2 - ry; } else { const s = 1 / Math.sqrt(r); x = W / 2 + ddx * s; y = H / 2 + ddy * s; }
      }
    }
    if (S.cx == null) { S.cx = x; S.cy = y; }
    const k = Math.min(1, dt * 12);
    S.cx += (x - S.cx) * k; S.cy += (y - S.cy) * k;
    this.call.style.transform = `translate3d(${S.cx.toFixed(1)}px,${S.cy.toFixed(1)}px,0)`;
    if (edge !== S.L.edge) { S.L.edge = edge; this.call.classList.toggle('is-edge', edge); }
    if (edge) this.callEdge.style.transform = `rotate(${ang.toFixed(3)}rad)`;
    // CHARGE!: the arrow points where it's going to run (boss forward, projected)
    if (this.call.dataset.move === 'charge') {
      const b = this._b();
      let da = 0;
      const p = b && (b.pos || (b.root && b.root.position));
      if (p) {
        const mp = b.move && (b.move.p || b.move.params);
        const yaw = mp && Number.isFinite(mp.yaw) ? mp.yaw : b.yaw ?? (b.root ? b.root.rotation.y : 0);
        const d = mp && mp.dir;
        const fx = d ? d.x : Math.sin(yaw), fz = d ? d.z : Math.cos(yaw);
        const w0 = this._chargeWorld0 || (this._chargeWorld0 = {}), w1 = this._chargeWorld1 || (this._chargeWorld1 = {});
        w0.x = p.x; w0.y = p.y + 1; w0.z = p.z;
        w1.x = p.x + fx * 6; w1.y = p.y + 1; w1.z = p.z + fz * 6;
        const a0 = this._screen(w0, this._chargeScreen0 || (this._chargeScreen0 = {})), a1 = this._screen(w1, this._chargeScreen1 || (this._chargeScreen1 = {}));
        if (a0 && a1 && !a0.behind && !a1.behind) da = Math.atan2(a1.y - a0.y, a1.x - a0.x);
        else { const cam = G.camera; if (cam && cam.matrixWorld) { const e = cam.matrixWorld.elements; da = Math.atan2(-(fx * -e[8] + fz * -e[10]), fx * e[0] + fz * e[2]); } }
      }
      this.callArrow.style.transform = `rotate(${da.toFixed(3)}rad)`;
    }
  }

_updBeacons.source:
_updBeacons(bw, bh, dt, u = 16) {
    const M = this._map, L = this._L;
    const vis = this._mapT > 0.02;
    if (vis !== L.bcnVis) { L.bcnVis = vis; this.map.classList.toggle('has-beacons', vis); }
    if (!vis) return;
    const tg = this._beaconTargets();
    this._ensureJumpSlots(tg.length);
    M.targetKeys = tg.map((b) => b?.kind === 'bubbler'
      ? { kind: 'bubbler', id: b.domeId, serial: b.serial, team: b.team } : null);
    for (let i = tg.length; i < this.beacons.length; i++) {
      this.beacons[i].style.display = 'none';
      this._updLegendRow(i, null, false);
    }
    const me = this._local();
    const canJump = this.lab ? true : (me && G.match?.controller?.a === me ? G.match.controller.canRequestMapJump() : !!me?.canSuperJump?.());
    // virtual cursor (pointer is locked in-game: steer with mouse deltas; magnet toward beacons)
    const inp = G.input;
    const padChoice = M.open && inp?.lastDevice === 'pad' && inp.pad?.mapping === 'standard';
    if (L.padChoice && !padChoice) M.hover = -1;
    if (padChoice) M.hover = G.match?.controller?.padJumpIndex ?? -1;
    if (L.padChoice !== padChoice) {
      L.padChoice = padChoice;
      const foot = this.mapLegend.querySelector('.iw-lg__foot');
      if (foot) foot.innerHTML = padChoice
        ? (document.documentElement.lang === 'ja' ? '十字キーで選択 · LB/RBでバリアを選択 · 右のAボタンで確定 · Xで閉じる' : 'D-pad selects · LB/RB cycle Bubblers · right face A confirms · X closes')
        : richText('Press [1] – [9] or click · press [TAB] or [M] to close');
    }
    if (M.open && inp && inp.locked && !padChoice) {
      M.cx = clamp(M.cx + (inp.mouse.dx || 0) / Math.max(80, bw), 0.02, 0.98);
      M.cy = clamp(M.cy + (inp.mouse.dy || 0) / Math.max(80, bh), 0.02, 0.98);
      let best = -1, bd = 0.09;
      for (let i = 0; i < tg.length; i++) {
        const b = tg[i]; if (!b) continue;
        const d = Math.hypot((b.x - M.cx) * bw, (b.y - M.cy) * bh) / Math.max(bw, bh);
        if (d < bd) { bd = d; best = i; }
      }
      if (best !== M.hover) { M.hover = best; if (best >= 0) this._snd('ui_hover', { volume: 0.45 }); }
      if (inp.mouse.leftPressed && M.hover >= 0) this._jumpTo(M.hover);
      this.mapCursor.style.transform = `translate3d(${(M.cx * bw).toFixed(1)}px,${(M.cy * bh).toFixed(1)}px,0)`;
      this.mapCursor.classList.toggle('is-snap', M.hover >= 0);
    }
    const cursorOn = !!(M.open && inp && inp.locked && !padChoice);
    if (cursorOn !== L.curOn) { L.curOn = cursorOn; this.mapCursor.classList.toggle('is-on', cursorOn); }
    // number keys pressed this frame → flash the matching beacon (the controller performs the jump)
    if (M.open && inp) for (let i = 0; i < Math.min(tg.length, 9); i++) if (inp.wasPressed && inp.wasPressed('Digit' + (i + 1))) { M.pressed = i; M.pressT = 0.5; this._restart(this.beacons[i], 'is-press'); }
    M.pressT = Math.max(0, M.pressT - dt);
    // spread overlapping beacons apart (allies often stand together at spawn); stems point at the true spots
    const P = this._bcnP || (this._bcnP = []);
    while (P.length < tg.length) P.push({ x: 0, y: 0, ox: 0, oy: 0, on: false });
    const minD = u * 3.4 * 1.3 * (this._mapT > 0.5 ? 1 : 0.6);
    for (let i = 0; i < tg.length; i++) { const b = tg[i], p = P[i]; p.on = !!b; if (b) { p.x = p.ox = b.x * bw; p.y = p.oy = b.y * bh; } }
    for (let it = 0; it < 6; it++) {
      let moved = false;
      for (let i = 0; i < tg.length; i++) for (let j = i + 1; j < tg.length; j++) {
        const a = P[i], c = P[j]; if (!a.on || !c.on) continue;
        let dx = c.x - a.x, dy = c.y - a.y, d = Math.hypot(dx, dy);
        if (d >= minD) continue;
        if (d < 0.5) { const ang = (i * 2.1 + j * 1.3); dx = Math.cos(ang); dy = Math.sin(ang); d = 1; }
        const push = (minD - d) / 2;
        moved = true;
        a.x -= (dx / d) * push; a.y -= (dy / d) * push; c.x += (dx / d) * push; c.y += (dy / d) * push;
      }
      if (!moved) break;
    }
    for (let i = 0; i < tg.length; i++) {
      const el = this.beacons[i], b = tg[i], p = P[i];
      const key = b ? `${p.x.toFixed(0)}|${p.y.toFixed(0)}|${p.ox.toFixed(0)}|${p.oy.toFixed(0)}|${b.ok ? 1 : 0}|${b.dead ? 1 : 0}|${M.hover === i ? 1 : 0}|${canJump ? 1 : 0}|${b.name}` : 'x';
      this._updLegendRow(i, b, canJump);
      if (el._key === key) continue;
      el._key = key;
      if (!b) { el.style.display = 'none'; continue; }
      el.style.display = '';
      el.style.transform = `translate3d(${p.x.toFixed(1)}px,${p.y.toFixed(1)}px,0)`;
      const sx = p.ox - p.x, sy = p.oy - p.y, sl = Math.hypot(sx, sy);
      const stem = el.firstChild;
      if (sl > 3) { stem.style.display = ''; stem.style.width = sl.toFixed(1) + 'px'; stem.style.transform = `rotate(${Math.atan2(sy, sx).toFixed(3)}rad)`; }
      else stem.style.display = 'none';
      el.classList.toggle('is-off', !b.ok || !canJump);
      el.classList.toggle('is-hover', M.hover === i && b.ok && canJump);
      el.classList.toggle('iw-bcn--bubbler', b.kind === 'bubbler');
      if (!b.home) {
        if (el._w !== b.weapon || el._kind !== b.kind) {
          el._w = b.weapon; el._kind = b.kind;
          el.querySelector('.iw-bcn__icon').innerHTML = b.kind === 'bubbler' ? BUBBLER_ICON : weaponIcon(kindOf(b.weapon));
        }
        const keyEl = el.querySelector('.iw-bcn__key');
        const key = i < 9 ? String(i + 1) : '';
        keyEl.textContent = key; keyEl.style.display = key ? '' : 'none';
        el.querySelector('.iw-bcn__label b').textContent = b.ok ? b.name : `${b.name} · ${b.dead ? '×' : '…'}`;
      }
    }
    // dashed jump arc from you to the hovered beacon
    const hb = M.hover >= 0 ? tg[M.hover] : null;
    const showLine = !!(hb && hb.ok && canJump && M.sx != null);
    if (showLine !== L.jl) { L.jl = showLine; this.mapJumpLine.classList.toggle('is-on', showLine); }
    if (showLine) {
      const x0 = M.sx * bw, y0 = M.sy * bh, x1 = hb.x * bw, y1 = hb.y * bh;
      const mx = (x0 + x1) / 2, my = (y0 + y1) / 2 - Math.hypot(x1 - x0, y1 - y0) * 0.35;
      const d = `M${x0.toFixed(1)} ${y0.toFixed(1)} Q${mx.toFixed(1)} ${my.toFixed(1)} ${x1.toFixed(1)} ${y1.toFixed(1)}`;
      if (d !== L.jlD) { L.jlD = d; const svg = this.mapJumpLine.firstChild; svg.setAttribute('width', bw.toFixed(0)); svg.setAttribute('height', bh.toFixed(0)); svg.firstChild.setAttribute('d', d); }
    }
  }
